13	// Binds a single inbound record from Kafka client with its delivery information.
14	struct OutboundRecord {
15	
16	  // These fields were received from downstream.
17	  const std::string topic_;
18	  const int32_t partition_;
19	  const absl::string_view key_;
20	  const absl::string_view value_;
21	
22	  // These fields will get updated when delivery to upstream Kafka cluster finishes.
23	  int16_t error_code_;
24	  uint32_t saved_offset_;
25	
26	  OutboundRecord(const std::string& topic, const int32_t partition, const absl::string_view key,
27	                 const absl::string_view value)
28	      : topic_{topic}, partition_{partition}, key_{key}, value_{value}, error_code_{0},
29	        saved_offset_{0} {};
30	};
