9	class LibRdKafkaUtilsImpl : public LibRdKafkaUtils {
10	
11	  // LibRdKafkaUtils
12	  RdKafka::Conf::ConfResult setConfProperty(RdKafka::Conf& conf, const std::string& name,
13	                                            const std::string& value,
14	                                            std::string& errstr) const override {
15	    return conf.set(name, value, errstr);
16	  }
17	
18	  // LibRdKafkaUtils
19	  RdKafka::Conf::ConfResult setConfDeliveryCallback(RdKafka::Conf& conf,
20	                                                    RdKafka::DeliveryReportCb* dr_cb,
21	                                                    std::string& errstr) const override {
22	    return conf.set("dr_cb", dr_cb, errstr);
23	  }
24	
25	  // LibRdKafkaUtils
26	  std::unique_ptr<RdKafka::Producer> createProducer(RdKafka::Conf* conf,
27	                                                    std::string& errstr) const override {
28	    return std::unique_ptr<RdKafka::Producer>(RdKafka::Producer::create(conf, errstr));
29	  }
30	};
