32	RichKafkaProducer::RichKafkaProducer(Event::Dispatcher& dispatcher,
33	                                     Thread::ThreadFactory& thread_factory,
34	                                     const RawKafkaProducerConfig& configuration)
35	    : RichKafkaProducer(dispatcher, thread_factory, configuration, LibRdKafkaUtilsImpl{}){};
36	
37	RichKafkaProducer::RichKafkaProducer(Event::Dispatcher& dispatcher,
38	                                     Thread::ThreadFactory& thread_factory,
39	                                     const RawKafkaProducerConfig& configuration,
40	                                     const LibRdKafkaUtils& utils)
41	    : dispatcher_{dispatcher} {
42	
43	  // Create producer configuration object.
44	  std::unique_ptr<RdKafka::Conf> conf =
45	      std::unique_ptr<RdKafka::Conf>(RdKafka::Conf::create(RdKafka::Conf::CONF_GLOBAL));
46	  std::string errstr;
47	
48	  // Setup producer custom properties.
49	  for (const auto& e : configuration) {
50	    if (utils.setConfProperty(*conf, e.first, e.second, errstr) != RdKafka::Conf::CONF_OK) {
51	      throw EnvoyException(absl::StrCat("Could not set producer property [", e.first, "] to [",
52	                                        e.second, "]:", errstr));
53	    }
54	  }
55	
56	  // Setup callback (this callback is going to be invoked in dedicated monitoring thread).
57	  if (utils.setConfDeliveryCallback(*conf, this, errstr) != RdKafka::Conf::CONF_OK) {
58	    throw EnvoyException(absl::StrCat("Could not set producer callback:", errstr));
59	  }
60	
61	  // Finally, we create the producer.
62	  producer_ = utils.createProducer(conf.get(), errstr);
63	  if (!producer_) {
64	    throw EnvoyException(absl::StrCat("Could not create producer:", errstr));
65	  }
66	
67	  // Start the monitoring thread.
68	  poller_thread_active_ = true;
69	  std::function<void()> thread_routine = [this]() -> void { checkDeliveryReports(); };
70	  poller_thread_ = thread_factory.createThread(thread_routine);
71	}
72	
73	RichKafkaProducer::~RichKafkaProducer() {
74	  ENVOY_LOG(debug, "Shutting down worker thread");
75	  poller_thread_active_ = false; // This should never be needed, as we call 'markFinished' earlier.
76	  poller_thread_->join();
77	  ENVOY_LOG(debug, "Worker thread shut down successfully");
78	}
79	
80	void RichKafkaProducer::markFinished() { poller_thread_active_ = false; }
81	
82	void RichKafkaProducer::send(const ProduceFinishCbSharedPtr origin, const std::string& topic,
83	                             const int32_t partition, const absl::string_view key,
84	                             const absl::string_view value) {
85	  {
86	    void* value_data = const_cast<char*>(value.data()); // Needed for Kafka API.
87	    // Data is a pointer into request internals, and it is going to be managed by
88	    // ProduceRequestHolder lifecycle. So we are not going to use any of librdkafka's memory
89	    // management.
90	    const int flags = 0;
91	    const RdKafka::ErrorCode ec = producer_->produce(
92	        topic, partition, flags, value_data, value.size(), key.data(), key.size(), 0, nullptr);
93	    if (RdKafka::ERR_NO_ERROR == ec) {
94	      // We have succeeded with submitting data to producer, so we register a callback.
95	      unfinished_produce_requests_.push_back(origin);
96	    } else {
97	      // We could not submit data to producer.
98	      // Let's treat that as a normal failure (Envoy is a broker after all) and propagate
99	      // downstream.
100	      ENVOY_LOG(trace, "Produce failure: {}, while sending to [{}/{}]", ec, topic, partition);
101	      const DeliveryMemento memento = {value_data, ec, 0};
102	      origin->accept(memento);
103	    }
104	  }
105	}
106	
107	void RichKafkaProducer::checkDeliveryReports() {
108	  while (poller_thread_active_) {
109	    // We are going to wait for 1000ms, returning when an event (message delivery) happens or
110	    // producer is closed. Unfortunately we do not have any ability to interrupt this call, so every
111	    // destructor is going to take up to this much time.
112	    producer_->poll(1000);
113	    // This invokes the callback below, if any delivery finished (successful or not).
114	  }
115	  ENVOY_LOG(debug, "Poller thread finished");
116	}
117	
118	// Kafka callback that contains the delivery information.
119	void RichKafkaProducer::dr_cb(RdKafka::Message& message) {
120	  ENVOY_LOG(trace, "Delivery finished: {}, payload has been saved at offset {} in {}/{}",
121	            message.err(), message.topic_name(), message.partition(), message.offset());
122	  const DeliveryMemento memento = {message.payload(), message.err(), message.offset()};
123	  // Because this method gets executed in poller thread, we need to pass the data through
124	  // dispatcher.
125	  const Event::PostCb callback = [this, memento]() -> void { processDelivery(memento); };
126	  dispatcher_.post(callback);
127	}
128	
129	// We got the delivery data.
130	// Now we just check all unfinished requests, find the one that originated this particular delivery,
131	// and notify it.
132	void RichKafkaProducer::processDelivery(const DeliveryMemento& memento) {
133	  for (auto it = unfinished_produce_requests_.begin(); it != unfinished_produce_requests_.end();) {
134	    bool accepted = (*it)->accept(memento);
135	    if (accepted) {
136	      unfinished_produce_requests_.erase(it);
137	      break; // This is important - a single request can be mapped into multiple callbacks here.
138	    } else {
139	      ++it;
140	    }
141	  }
142	}
143	
144	std::list<ProduceFinishCbSharedPtr>& RichKafkaProducer::getUnfinishedRequestsForTest() {
145	  return unfinished_produce_requests_;
146	}
