1	#include "contrib/kafka/filters/network/source/mesh/command_handlers/produce_record_extractor.h"
2	
3	namespace Envoy {
4	namespace Extensions {
5	namespace NetworkFilters {
6	namespace Kafka {
7	namespace Mesh {
8	
9	std::vector<OutboundRecord>
10	RecordExtractorImpl::extractRecords(const std::vector<TopicProduceData>& data) const {
11	  std::vector<OutboundRecord> result;
12	  for (const auto& topic_data : data) {
13	    for (const auto& partition_data : topic_data.partition_data_) {
14	      // Kafka protocol allows nullable data.
15	      if (partition_data.records_) {
16	        const auto topic_result = extractPartitionRecords(topic_data.name_, partition_data.index_,
17	                                                          *(partition_data.records_));
18	        std::copy(topic_result.begin(), topic_result.end(), std::back_inserter(result));
19	      }
20	    }
21	  }
22	  return result;
23	}
24	
25	// Fields common to any record batch payload.
26	// See:
27	// https://github.com/apache/kafka/blob/2.4.1/clients/src/main/java/org/apache/kafka/common/record/DefaultRecordBatch.java#L46
28	constexpr unsigned int RECORD_BATCH_COMMON_FIELDS_SIZE = /* BaseOffset */ sizeof(int64_t) +
29	                                                         /* Length */ sizeof(int32_t) +
30	                                                         /* PartitionLeaderEpoch */ sizeof(int32_t);
31	
32	// Magic format introduced around Kafka 1.0.0 and still used with Kafka 2.4.
33	// We can extract records out of record batches that use this magic.
34	constexpr int8_t SUPPORTED_MAGIC = 2;
35	
36	// Reference implementation:
37	// https://github.com/apache/kafka/blob/2.4.1/clients/src/main/java/org/apache/kafka/common/record/DefaultRecordBatch.java#L443
38	std::vector<OutboundRecord> RecordExtractorImpl::extractPartitionRecords(const std::string& topic,
39	                                                                         const int32_t partition,
40	                                                                         const Bytes& bytes) const {
41	
42	  absl::string_view data = {reinterpret_cast<const char*>(bytes.data()), bytes.size()};
43	
44	  // Let's skip these common fields, because we are not using them.
45	  if (data.length() < RECORD_BATCH_COMMON_FIELDS_SIZE) {
46	    throw EnvoyException(fmt::format("record batch for [{}-{}] is too short (no common fields): {}",
47	                                     topic, partition, data.length()));
48	  }
49	  data = {data.data() + RECORD_BATCH_COMMON_FIELDS_SIZE,
50	          data.length() - RECORD_BATCH_COMMON_FIELDS_SIZE};
51	
52	  // Extract magic - it what is the format of records present in the bytes provided.
53	  Int8Deserializer magic_deserializer;
54	  magic_deserializer.feed(data);
55	  if (!magic_deserializer.ready()) {
56	    throw EnvoyException(
57	        fmt::format("magic byte is not present in record batch for [{}-{}]", topic, partition));
58	  }
59	
60	  // Old client sending old magic, or Apache Kafka introducing new magic.
61	  const int8_t magic = magic_deserializer.get();
62	  if (SUPPORTED_MAGIC != magic) {
63	    throw EnvoyException(fmt::format("unknown magic value in record batch for [{}-{}]: {}", topic,
64	                                     partition, magic));
65	  }
66	
67	  // We have received a record batch with good magic.
68	  return processRecordBatch(topic, partition, data);
69	}
70	
71	// Record batch fields we are going to ignore (because we rip it up and send its contents).
72	// See:
73	// https://github.com/apache/kafka/blob/2.4.1/clients/src/main/java/org/apache/kafka/common/record/DefaultRecordBatch.java#L50
74	// and:
75	// https://github.com/apache/kafka/blob/2.4.1/clients/src/main/java/org/apache/kafka/common/record/DefaultRecordBatch.java#L471
76	constexpr unsigned int IGNORED_FIELDS_SIZE =
77	    /* CRC */ sizeof(int32_t) + /* Attributes */ sizeof(int16_t) +
78	    /* LastOffsetDelta */ sizeof(int32_t) + /* FirstTimestamp */ sizeof(int64_t) +
79	    /* MaxTimestamp */ sizeof(int64_t) + /* ProducerId */ sizeof(int64_t) +
80	    /* ProducerEpoch */ sizeof(int16_t) + /* BaseSequence */ sizeof(int32_t) +
81	    /* RecordCount */ sizeof(int32_t);
82	
83	std::vector<OutboundRecord> RecordExtractorImpl::processRecordBatch(const std::string& topic,
84	                                                                    const int32_t partition,
85	                                                                    absl::string_view data) const {
86	
87	  if (data.length() < IGNORED_FIELDS_SIZE) {
88	    throw EnvoyException(
89	        fmt::format("record batch for [{}-{}] is too short (no attribute fields): {}", topic,
90	                    partition, data.length()));
91	  }
92	  data = {data.data() + IGNORED_FIELDS_SIZE, data.length() - IGNORED_FIELDS_SIZE};
93	
94	  // We have managed to consume all the fancy bytes, now it's time to get to records.
95	  std::vector<OutboundRecord> result;
96	  while (!data.empty()) {
97	    const OutboundRecord record = extractRecord(topic, partition, data);
98	    result.push_back(record);
99	  }
100	  return result;
101	}
102	
103	// Reference implementation:
104	// https://github.com/apache/kafka/blob/2.4.1/clients/src/main/java/org/apache/kafka/common/record/DefaultRecord.java#L179
105	OutboundRecord RecordExtractorImpl::extractRecord(const std::string& topic, const int32_t partition,
106	                                                  absl::string_view& data) const {
107	
108	  VarInt32Deserializer length;
109	  length.feed(data);
110	  if (!length.ready()) {
111	    throw EnvoyException(
112	        fmt::format("record for [{}-{}] is too short (no length)", topic, partition));
113	  }
114	  const int32_t len = length.get();
115	  if (len < 0) {
116	    throw EnvoyException(
117	        fmt::format("record for [{}-{}] has invalid length: {}", topic, partition, len));
118	  }
119	  if (static_cast<uint32_t>(len) > data.length()) {
120	    throw EnvoyException(fmt::format("record for [{}-{}] is too short (not enough bytes provided)",
121	                                     topic, partition));
122	  }
123	
124	  const absl::string_view expected_end_of_record = {data.data() + len, data.length() - len};
125	
126	  // We throw away the following batch fields: attributes, timestamp delta, offset delta (cannot do
127	  // an easy jump, as some are variable-length).
128	  Int8Deserializer attributes;
129	  attributes.feed(data);
130	  VarInt64Deserializer tsDelta;
131	  tsDelta.feed(data);
132	  VarUInt32Deserializer offsetDelta;
133	  offsetDelta.feed(data);
134	  if (!attributes.ready() || !tsDelta.ready() || !offsetDelta.ready()) {
135	    throw EnvoyException(
136	        fmt::format("attributes not present in record for [{}-{}]", topic, partition));
137	  }
138	
139	  // Record key and value.
140	  const absl::string_view key = extractByteArray(data);
141	  const absl::string_view value = extractByteArray(data);
142	
